renderer.fragment:
void main(){
  float asp = iResolution.x / max(iResolution.y, 1.0);
  vec2 p = vec2(uv.x * asp, uv.y);
  vec4 acc = vec4(0.0);
  for (int L = 0; L < 4; L++) {
    float fl = float(L);
    float sc = 6.0 + fl * 3.0;
    float sp = 0.22 - 0.03 * fl;
    vec2 q = p * sc + vec2(-u_wind * iTime * sp * sc * 0.6, iTime * sp * sc);
    vec2 id = floor(q);
    vec2 f = fract(q) - 0.5;
    float h = hash(id + fl * 17.3);
    if (h > u_density) continue;
    float h2 = hash(id + vec2(3.1, 7.7) + fl);
    float h3 = hash(id + vec2(11.0, 5.0) + fl);
    vec2 c = (vec2(h2, h3) - 0.5) * 0.3;
    c.x += 0.1 * sin(iTime * (1.0 + 2.0 * h2) + h * 6.2832);
    vec2 d = f - c;
    float dir = h2 > 0.5 ? 1.0 : -1.0;
    float ang = iTime * (1.0 + 3.0 * h3) * dir + h * 6.2832 + u_wind * 0.5;
    d = rot(ang) * d;
    float flip = cos(iTime * (2.0 + 4.0 * h2) + h3 * 6.2832);
    d.x /= max(abs(flip), 0.15);
    float sz = 0.1 + 0.06 * h3;
    float sd = h2 < 0.3 ? sdCircle(d, sz * 0.8) : sdBox(d, vec2(sz, sz * 0.45));
    float aa = sc / max(iResolution.y, 1.0) * 1.5;
    float a = 1.0 - smoothstep(-aa, aa, sd);
    vec3 col = hsv2rgb(vec3(fract(h * 7.13 + h3), 0.75, 1.0));
    col *= 0.55 + 0.45 * abs(flip);
    acc.rgb += col * a * (1.0 - acc.a);
    acc.a += a * (1.0 - acc.a);
  }
  fragColor = vec4(acc.rgb / max(acc.a, 1e-4), acc.a);
}
